import { Node, Rect, Size, Sprite, SpriteFrame, Texture2D, UITransform } from 'cc';
import type { AssetService } from '../../../services/asset/AssetService';
import { CITY_ALTITUDES } from './CityBloxxTheme';

/** Generated by tools/city-bloxx/prepare-skyward.py: blended seams are identical in both neighbors. */
export interface CitySkyPanels {
    width: number;
    overlap: number;
    panels: { path: string; height: number }[];
}
interface Panel { path: string; height: number; start: number; node: Node; life: Node; frame?: SpriteFrame; loading?: Promise<void>; retryAt: number; }

/**
 * One continuous painted ascent. Panel i reaches the screen bottom at the
 * first floor of altitude i, so the next region is always visible above.
 */
export class CityBloxxSky {
    readonly root: Node;
    private readonly panels: Panel[] = [];
    private readonly keys: { floor: number; offset: number; slope: number }[] = [];
    private keysView = -1;
    private disposed = false;
    private width = 750;
    private height = 1334;

    constructor(parent: Node, private readonly bundle: string, private readonly assets: AssetService, private readonly data: CitySkyPanels) {
        if (data.panels.length !== CITY_ALTITUDES.length) throw Error('City sky panels must match the altitude stages');
        this.root = new Node('CitySkyAscent'); this.root.layer = parent.layer; parent.addChild(this.root);
        this.root.addComponent(UITransform);
        let start = 0;
        for (const p of data.panels) {
            const node = new Node('CitySky-' + p.path.split('/').pop()); node.layer = parent.layer;
            this.root.addChild(node); node.addComponent(UITransform).setAnchorPoint(.5, 0);
            node.addComponent(Sprite).sizeMode = Sprite.SizeMode.CUSTOM; node.active = false;
            const life = new Node('CitySkyLife'); life.layer = parent.layer; node.addChild(life); life.addComponent(UITransform);
            this.panels.push({ path: p.path, height: p.height, start, node, life, retryAt: 0 });
            start += p.height - data.overlap;
        }
    }
    /** Each on-screen region's life container, drawn right over its painted panel in panel pixels (origin bottom center). */
    visitRegions(visit: (index: number, node: Node, height: number) => void): void {
        this.panels.forEach((p, i) => { if (p.node.active) visit(i, p.life, p.height); });
    }
    /** The first two regions are part of the opening screen. */
    async preload(): Promise<void> { await Promise.all(this.panels.slice(0, 2).map(p => this.load(p))); }

    layout(width: number, height: number): void {
        this.width = width; this.height = height;
        const scale = width / this.data.width;
        this.root.setScale(scale, scale, 1);
    }
    /**
     * Monotone cubic keys avoid speed kinks where regions have different floor
     * spans. No key may scroll past the last panel's top reaching the screen top.
     */
    private buildKeys(view: number): void {
        this.keysView = view;
        const last = this.panels[this.panels.length - 1], top = last.start + last.height - view;
        const points = CITY_ALTITUDES.map((a, i) => ({ floor: a.floor, offset: Math.min(this.panels[i].start, top) }));
        points.push({ floor: CITY_ALTITUDES[CITY_ALTITUDES.length - 1].floor + 160, offset: top });
        const secants = points.slice(1).map((p, i) => (p.offset - points[i].offset) / (p.floor - points[i].floor));
        this.keys.length = 0;
        points.forEach((p, i) => {
            const a = secants[i - 1] ?? secants[0], b = secants[i] ?? secants[secants.length - 1];
            this.keys.push({ ...p, slope: a * b <= 0 ? 0 : 2 * a * b / (a + b) });
        });
    }
    /** `floors` is the continuous camera altitude, including the intro descent. */
    update(floors: number): void {
        const scale = this.width / this.data.width, view = this.height / scale;
        if (view !== this.keysView) this.buildKeys(view);
        const offset = this.offsetAt(Math.max(0, floors)), bottom = -view / 2;
        for (let i = 0; i < this.panels.length; i++) {
            const p = this.panels[i], y = p.start - offset;
            const visible = y < view && y + p.height > 0;
            // Stream one region ahead; a panel is ready long before its seam enters.
            if (!p.frame && !p.loading && y < view * 2 && y + p.height > -view) void this.load(p);
            p.node.active = visible && !!p.frame;
            if (p.node.active && p.node.position.y !== bottom + y) p.node.setPosition(0, bottom + y);
        }
    }
    private offsetAt(floor: number): number {
        const k = this.keys;
        if (floor >= k[k.length - 1].floor) return k[k.length - 1].offset;
        let i = 0; while (floor > k[i + 1].floor) i++;
        const a = k[i], b = k[i + 1], h = b.floor - a.floor, t = (floor - a.floor) / h;
        const t2 = t * t, t3 = t2 * t;
        return (2 * t3 - 3 * t2 + 1) * a.offset + (t3 - 2 * t2 + t) * h * a.slope
            + (-2 * t3 + 3 * t2) * b.offset + (t3 - t2) * h * b.slope;
    }
    private load(p: Panel): Promise<void> {
        if (p.frame || this.disposed || Date.now() < p.retryAt) return p.loading ?? Promise.resolve();
        if (p.loading) return p.loading;
        p.loading = this.assets.loadAsset(this.bundle, p.path + '/texture', Texture2D).then(texture => {
            if (this.disposed) return;
            const frame = this.assets.createSpriteFrame(this.bundle, texture);
            frame.packable = false; frame.rect = new Rect(0, 0, texture.width, texture.height);
            frame.originalSize = new Size(texture.width, texture.height);
            p.frame = frame; p.node.getComponent(Sprite)!.spriteFrame = frame;
            p.node.getComponent(UITransform)!.setContentSize(this.data.width, p.height);
        }, () => { p.loading = undefined; p.retryAt = Date.now() + 3000; });
        return p.loading;
    }
    dispose(): void {
        this.disposed = true;
        this.panels.forEach(p => { if (p.frame) this.assets.releaseRuntimeAsset(p.frame); p.frame = undefined; });
        this.root.destroy();
    }
}
